#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

static void check_fp32_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(tensor.dtype() == torch::kFloat32,
                name, " must be float32, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry for the FLUX feedforward.
// Per definition.json:
//   hidden_states : [B, S, hidden_dim=3072] fp32
//   fc1_weight    : [mlp_hidden_dim=12288, hidden_dim=3072] fp32
//   fc1_bias      : [mlp_hidden_dim=12288] fp32
//   fc2_weight    : [hidden_dim=3072, mlp_hidden_dim=12288] fp32
//   fc2_bias      : [hidden_dim=3072] fp32
//   output        : [B, S, hidden_dim=3072] fp32 (DPS)
//
// Const axes pinned by definition.json AND enforced on every tensor
// the kernel indexes with that fixed assumption:
//   hidden_dim     = 3072
//   mlp_hidden_dim = 12288

void run(
    torch::Tensor hidden_states,
    torch::Tensor fc1_weight,
    torch::Tensor fc1_bias,
    torch::Tensor fc2_weight,
    torch::Tensor fc2_bias,
    torch::Tensor output
) {
    check_fp32_contiguous_cuda(hidden_states, "hidden_states");
    check_fp32_contiguous_cuda(fc1_weight, "fc1_weight");
    check_fp32_contiguous_cuda(fc1_bias, "fc1_bias");
    check_fp32_contiguous_cuda(fc2_weight, "fc2_weight");
    check_fp32_contiguous_cuda(fc2_bias, "fc2_bias");
    check_fp32_contiguous_cuda(output, "output");

    TORCH_CHECK(hidden_states.dim() == 3,
                "hidden_states must be 3D [B, S, hidden_dim]");
    TORCH_CHECK(fc1_weight.dim() == 2, "fc1_weight must be 2D");
    TORCH_CHECK(fc1_bias.dim() == 1, "fc1_bias must be 1D");
    TORCH_CHECK(fc2_weight.dim() == 2, "fc2_weight must be 2D");
    TORCH_CHECK(fc2_bias.dim() == 1, "fc2_bias must be 1D");
    TORCH_CHECK(output.dim() == 3,
                "output must be 3D [B, S, hidden_dim]");

    constexpr int64_t kHiddenDim = 3072;
    constexpr int64_t kMlpHiddenDim = 12288;

    TORCH_CHECK(hidden_states.size(2) == kHiddenDim,
                "hidden_states.size(2) must equal hidden_dim=3072, got ",
                hidden_states.size(2));
    TORCH_CHECK(fc1_weight.size(0) == kMlpHiddenDim,
                "fc1_weight.size(0) must equal mlp_hidden_dim=12288, got ",
                fc1_weight.size(0));
    TORCH_CHECK(fc1_weight.size(1) == kHiddenDim,
                "fc1_weight.size(1) must equal hidden_dim=3072, got ",
                fc1_weight.size(1));
    TORCH_CHECK(fc1_bias.size(0) == kMlpHiddenDim,
                "fc1_bias.size(0) must equal mlp_hidden_dim=12288, got ",
                fc1_bias.size(0));
    TORCH_CHECK(fc2_weight.size(0) == kHiddenDim,
                "fc2_weight.size(0) must equal hidden_dim=3072, got ",
                fc2_weight.size(0));
    TORCH_CHECK(fc2_weight.size(1) == kMlpHiddenDim,
                "fc2_weight.size(1) must equal mlp_hidden_dim=12288, got ",
                fc2_weight.size(1));
    TORCH_CHECK(fc2_bias.size(0) == kHiddenDim,
                "fc2_bias.size(0) must equal hidden_dim=3072, got ",
                fc2_bias.size(0));

    TORCH_CHECK(output.size(0) == hidden_states.size(0),
                "output.size(0) must equal hidden_states.size(0)");
    TORCH_CHECK(output.size(1) == hidden_states.size(1),
                "output.size(1) must equal hidden_states.size(1)");
    TORCH_CHECK(output.size(2) == kHiddenDim,
                "output.size(2) must equal hidden_dim=3072, got ",
                output.size(2));

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_037_flux_feedforward_gelu_approximate_launcher(
        hidden_states, fc1_weight, fc1_bias,
        fc2_weight, fc2_bias, output, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "fp32 FLUX feedforward: CUTLASS Sm80 TensorOp GEMM 1 "
        "(fp32 tf32 mma) + GELU-tanh+bias kernel + CUTLASS Sm80 "
        "TensorOp GEMM 2 + bias-add kernel. hidden_dim=3072, "
        "mlp_hidden_dim=12288 pinned. Destination-passing style.");
}

#include "kernel.h"

#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

#include <cutlass/gemm/device/gemm.h>
#include <cutlass/numeric_types.h>
#include <cutlass/layout/matrix.h>
#include <cutlass/arch/arch.h>
#include <cutlass/arch/mma.h>
#include <cutlass/epilogue/thread/linear_combination.h>

// Four-kernel chain for the FLUX feedforward (fp32):
//
//   GEMM 1 : workspace[B*S, 12288] = hidden_states[B*S, 3072]
//                                     @ fc1_weight^T[3072, 12288]
//            (CUTLASS Sm80 TensorOp tf32 mma; same row-major-to-
//            mixed-layout encoding as the landed problem_004 /
//            problem_007 / problem_011 GEMM cohort.)
//
//   ACT    : per-(b, s, n) thread reads workspace[bs, n], adds
//            fc1_bias[n], applies GELU-tanh approximation, writes
//            back to workspace[bs, n].
//
//   GEMM 2 : output[B*S, 3072] = workspace[B*S, 12288]
//                                @ fc2_weight^T[12288, 3072]
//            (same CUTLASS template).
//
//   BIAS   : per-(b, s, n) thread reads output[bs, n], adds
//            fc2_bias[n], writes back.
//
// Const axes pinned by the problem definition:
//   hidden_dim     = 3072
//   mlp_hidden_dim = 12288

namespace {

constexpr int kHiddenDim = 3072;
constexpr int kMlpHiddenDim = 12288;
constexpr int kBlockThreads = 256;

using ElementInputA = float;
using ElementInputB = float;
using ElementOutput = float;
using ElementAccumulator = float;

using LayoutInputA = cutlass::layout::RowMajor;
using LayoutInputB = cutlass::layout::ColumnMajor;
using LayoutOutput = cutlass::layout::RowMajor;

using MMAOp = cutlass::arch::OpClassTensorOp;
using SmArch = cutlass::arch::Sm80;

// fp32 Sm80 TensorOp uses mma.m16n8k8 tf32 mma internally (matches
// cuBLAS sgemm's tf32 default on Ampere). ThreadblockShape tiles
// 128x128 over M/N with 16 elements per tile-K column (fp32 fits
// fewer K elements per stage than fp16/bf16).
using ThreadblockShape = cutlass::gemm::GemmShape<128, 128, 16>;
using WarpShape = cutlass::gemm::GemmShape<64, 64, 16>;
using InstructionShape = cutlass::gemm::GemmShape<16, 8, 8>;

using EpilogueOp = cutlass::epilogue::thread::LinearCombination<
    ElementOutput,
    128 / cutlass::sizeof_bits<ElementOutput>::value,  // = 4
    ElementAccumulator,
    ElementAccumulator>;

using SwizzleThreadBlock =
    cutlass::gemm::threadblock::GemmIdentityThreadblockSwizzle<>;
constexpr int kNumStages = 3;

using CutlassGemm = cutlass::gemm::device::Gemm<
    ElementInputA, LayoutInputA,
    ElementInputB, LayoutInputB,
    ElementOutput, LayoutOutput,
    ElementAccumulator,
    MMAOp,
    SmArch,
    ThreadblockShape,
    WarpShape,
    InstructionShape,
    EpilogueOp,
    SwizzleThreadBlock,
    kNumStages>;

constexpr float kSqrt2OverPi = 0.7978845608028654f;
constexpr float kGeluTanhConst = 0.044715f;

__device__ __forceinline__ float gelu_tanh_approx(float z) {
    const float inner = kSqrt2OverPi * (z + kGeluTanhConst * z * z * z);
    return 0.5f * z * (1.0f + tanhf(inner));
}

__global__ void __launch_bounds__(kBlockThreads, 8)
    k_gelu_tanh_with_bias_inplace(
        float* __restrict__ workspace,
        const float* __restrict__ bias,
        int total_M
) {
    const size_t total_elements =
        (size_t)total_M * (size_t)kMlpHiddenDim;
    const size_t stride = (size_t)gridDim.x * (size_t)kBlockThreads;
    size_t i = (size_t)blockIdx.x * (size_t)kBlockThreads
               + (size_t)threadIdx.x;
    for (; i < total_elements; i += stride) {
        const int n = (int)(i % (size_t)kMlpHiddenDim);
        const float val = workspace[i] + bias[n];
        workspace[i] = gelu_tanh_approx(val);
    }
}

__global__ void __launch_bounds__(kBlockThreads, 8)
    k_bias_add_inplace(
        float* __restrict__ output,
        const float* __restrict__ bias,
        int total_M
) {
    const size_t total_elements =
        (size_t)total_M * (size_t)kHiddenDim;
    const size_t stride = (size_t)gridDim.x * (size_t)kBlockThreads;
    size_t i = (size_t)blockIdx.x * (size_t)kBlockThreads
               + (size_t)threadIdx.x;
    for (; i < total_elements; i += stride) {
        const int n = (int)(i % (size_t)kHiddenDim);
        output[i] += bias[n];
    }
}

void run_cutlass_gemm(
    const float* A_ptr, const float* B_ptr, float* C_ptr,
    int M, int N, int K,
    cudaStream_t stream
) {
    CutlassGemm gemm_op;
    CutlassGemm::Arguments args(
        {M, N, K},
        {A_ptr, K},
        {B_ptr, K},
        {C_ptr, N},
        {C_ptr, N},
        {1.0f, 0.0f});
    cutlass::Status status = gemm_op(args, nullptr, stream);
    TORCH_CHECK(
        status == cutlass::Status::kSuccess,
        "CUTLASS fp32 GEMM (problem_037) failed: ",
        cutlassGetStatusString(status));
}

}  // namespace

void problem_037_flux_feedforward_gelu_approximate_launcher(
    const torch::Tensor& hidden_states,
    const torch::Tensor& fc1_weight,
    const torch::Tensor& fc1_bias,
    const torch::Tensor& fc2_weight,
    const torch::Tensor& fc2_bias,
    torch::Tensor& output,
    cudaStream_t stream
) {
    const int B = static_cast<int>(hidden_states.size(0));
    const int S = static_cast<int>(hidden_states.size(1));
    const int M = B * S;

    auto workspace = torch::empty(
        {M, kMlpHiddenDim},
        torch::TensorOptions()
            .dtype(hidden_states.dtype())
            .device(hidden_states.device()));

    const float* hidden_states_ptr = hidden_states.data_ptr<float>();
    const float* fc1_weight_ptr = fc1_weight.data_ptr<float>();
    const float* fc1_bias_ptr = fc1_bias.data_ptr<float>();
    const float* fc2_weight_ptr = fc2_weight.data_ptr<float>();
    const float* fc2_bias_ptr = fc2_bias.data_ptr<float>();
    float* workspace_ptr = workspace.data_ptr<float>();
    float* output_ptr = output.data_ptr<float>();

    // GEMM 1: workspace = hidden_states @ fc1_weight^T.
    run_cutlass_gemm(
        hidden_states_ptr, fc1_weight_ptr, workspace_ptr,
        M, kMlpHiddenDim, kHiddenDim, stream);

    // GELU-tanh + bias in-place on workspace.
    {
        const size_t total_elements =
            (size_t)M * (size_t)kMlpHiddenDim;
        const int max_blocks = 65535;
        const int needed_blocks = static_cast<int>(
            (total_elements + kBlockThreads - 1) / kBlockThreads);
        const int num_blocks =
            needed_blocks < max_blocks ? needed_blocks : max_blocks;
        k_gelu_tanh_with_bias_inplace<<<num_blocks, kBlockThreads,
                                        0, stream>>>(
            workspace_ptr, fc1_bias_ptr, M);
        TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                    "problem_037 GELU+bias kernel launch failed");
    }

    // GEMM 2: output = workspace @ fc2_weight^T.
    run_cutlass_gemm(
        workspace_ptr, fc2_weight_ptr, output_ptr,
        M, kHiddenDim, kMlpHiddenDim, stream);

    // Bias-add in-place on output.
    {
        const size_t total_elements =
            (size_t)M * (size_t)kHiddenDim;
        const int max_blocks = 65535;
        const int needed_blocks = static_cast<int>(
            (total_elements + kBlockThreads - 1) / kBlockThreads);
        const int num_blocks =
            needed_blocks < max_blocks ? needed_blocks : max_blocks;
        k_bias_add_inplace<<<num_blocks, kBlockThreads, 0, stream>>>(
            output_ptr, fc2_bias_ptr, M);
        TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                    "problem_037 bias-add kernel launch failed");
    }
}

#pragma once

#include <torch/extension.h>
#include <cuda_runtime.h>

// Host launcher for the FLUX feedforward (fp32 Linear -> GELU-tanh
// -> Linear):
//
//   x_pre  = hidden_states[B*S, hidden_dim=3072]
//            @ fc1_weight^T[3072, mlp_hidden_dim=12288]
//   x_act  = gelu_tanh(x_pre + fc1_bias)
//   y_pre  = x_act[B*S, 12288] @ fc2_weight^T[12288, 3072]
//   output = y_pre + fc2_bias
//
// GELU-tanh approximation:
//   gelu_tanh(z) = 0.5 * z * (1 + tanh(sqrt(2/pi) * (z + 0.044715 * z^3)))
//
// Tensors:
//   hidden_states : [B, S, hidden_dim=3072] fp32
//   fc1_weight    : [mlp_hidden_dim=12288, hidden_dim=3072] fp32
//   fc1_bias      : [mlp_hidden_dim=12288] fp32
//   fc2_weight    : [hidden_dim=3072, mlp_hidden_dim=12288] fp32
//   fc2_bias      : [hidden_dim=3072] fp32
//   output        : [B, S, hidden_dim=3072] fp32 (DPS;
//                   pre-allocated by the eval driver).
//
// hidden_dim = 3072 and mlp_hidden_dim = 12288 are pinned by the
// problem definition; B and S vary per workload.
void problem_037_flux_feedforward_gelu_approximate_launcher(
    const torch::Tensor& hidden_states,
    const torch::Tensor& fc1_weight,
    const torch::Tensor& fc1_bias,
    const torch::Tensor& fc2_weight,
    const torch::Tensor& fc2_bias,
    torch::Tensor& output,
    cudaStream_t stream);
